import { PriceDataType } from '@/hooks/create-pool/useCreateDLMMPool'
import useDlmmPriceRange from '@/hooks/dlmm/useDlmmPriceRange'
import { Stack, StackProps } from '@chakra-ui/react'
import PriceInput from './PriceInput'

export default function ControlPriceRange({
  perText,
  direct,
  lowerPrice,
  upperPrice,
  wrapStyle = {}
}: {
  perText: string
  direct: boolean
  lowerPrice: PriceDataType | null
  upperPrice: PriceDataType | null
  wrapStyle?: StackProps
}) {
  const { handleAddPrice, handleSubPrice, onPriceChange } = useDlmmPriceRange()
  return (
    <Stack flexDir={{ base: 'column', lg: 'row' }} w="100%" gap={{ base: '8px', lg: '16px' }} {...wrapStyle}>
      <PriceInput
        title="Min Price"
        perText={perText}
        data={lowerPrice}
        onPriceChange={onPriceChange}
        direct={direct}
        loading={false}
        handleAddPrice={handleAddPrice}
        handleSubPrice={handleSubPrice}
      />
      <PriceInput
        title="Max Price"
        perText={perText}
        data={upperPrice}
        onPriceChange={onPriceChange}
        direct={direct}
        loading={false}
        handleAddPrice={handleAddPrice}
        handleSubPrice={handleSubPrice}
      />
    </Stack>
  )
}
