import { PoolApiInfo } from '@/types/pool'
import useTokenPrice from '@cetus/hooks/src/useTokenPrice'
import { d } from '@cetusprotocol/common-sdk'
import { BinAmount } from 'dd_dlmm_sdk'
import { useCallback, useEffect, useMemo, useState } from 'react'
import useFetchBinsTradeData from './useFetchBinsTradeData'

type WarpBinItem = {
  bin_id: number
  user_amount_a: string
  user_amount_b: string
  total_amount_a: string
  total_amount_b: string
}

/**
 * 计算用户在指定周期内的apr
 * https://m8bj5905cd.sg.larksuite.com/docx/NQOkdPWIBoi86vx0Cdru6yT0sCe
 * @param allBinList 所有仓位
 * @param user_bins 用户仓位
 * @param period 周期
 * @param dlmmApiPoolInfo 池子信息
 * @returns 用户在指定周期内的apr
 */
export function useDlmmApr(allBinList: BinAmount[], user_bins: BinAmount[], period: '24H' | '7D' | '30D', dlmmApiPoolInfo?: PoolApiInfo) {
  const [loading, setIsLoading] = useState<boolean>(false)
  const [feeDataObj, setFeeDataObj] = useState<Record<string, string>>({})
  const { fetchBinsTradeData } = useFetchBinsTradeData()

  const { getTokenAmountValue } = useTokenPrice()

  const getPeriodDays = useCallback((period: '24H' | '7D' | '30D') => {
    if (period === '24H') return 1
    if (period === '7D') return 7
    if (period === '30D') return 30
    return 1
  }, [])

  /**
   * 获取指定周期的费用数据
   */
  useEffect(() => {
    if (dlmmApiPoolInfo) {
      setIsLoading(true)
      fetchBinsTradeData({
        dataType: 'fee',
        period,
        poolId: dlmmApiPoolInfo?.poolAddress
      })
        .then(res => {
          const _feeDataObj: Record<string, string> = {}
          res.forEach(item => {
            _feeDataObj[`${item.binId}-${period}`] = item.value
          })
          setFeeDataObj({ ...feeDataObj, ..._feeDataObj })
        })
        .finally(() => {
          setIsLoading(false)
        })
    }
  }, [dlmmApiPoolInfo?.poolAddress, period])

  /**
   * 将用户仓位转换为warpBinList
   */
  const parseWarpUserBinList = useCallback(
    (user_bins: BinAmount[]) => {
      const warpBinList: WarpBinItem[] = []
      for (const bin of user_bins) {
        const binId = bin.bin_id
        const binInfo = allBinList.find(item => item.bin_id === binId)
        if (binInfo) {
          warpBinList.push({
            bin_id: binId,
            user_amount_a: bin.amount_a,
            user_amount_b: bin.amount_b,
            total_amount_a: binInfo.amount_a,
            total_amount_b: binInfo.amount_b
          })
        }
      }
      return warpBinList
    },
    [allBinList, period]
  )

  /**
   * 计算用户在指定周期内的费用
   * @param periodFee 费用
   * @param user_bins 用户仓位
   * @returns 用户在指定周期内的费用
   */
  const estimatedFee = useCallback(
    (user_bins: BinAmount[]) => {
      const warpBinList = parseWarpUserBinList(user_bins)
      let total_user_value = d(0)
      let total_fee = d(0)

      for (const bin of warpBinList) {
        const amount_value_a = getTokenAmountValue(bin.total_amount_a, dlmmApiPoolInfo?.tokenA?.coin_type)
        const amount_value_b = getTokenAmountValue(bin.total_amount_b, dlmmApiPoolInfo?.tokenB?.coin_type)
        const total_amount_value = d(amount_value_a).add(d(amount_value_b))

        const user_amount_value_a = getTokenAmountValue(bin.user_amount_a, dlmmApiPoolInfo?.tokenA?.coin_type)
        const user_amount_value_b = getTokenAmountValue(bin.user_amount_b, dlmmApiPoolInfo?.tokenB?.coin_type)
        const user_amount_value = d(user_amount_value_a).add(d(user_amount_value_b))
        total_user_value = total_user_value.add(user_amount_value)

        const total_fee_value = feeDataObj[`${bin.bin_id}-${period}`]
        const fee = d(user_amount_value)
          .mul(total_amount_value.add(user_amount_value))
          .mul(total_fee_value || '0')
        total_fee = d(total_fee).add(fee)
      }
      return {
        total_fee: total_fee.toString(),
        total_user_value: total_user_value.toString()
      }
    },
    [allBinList, feeDataObj, period]
  )

  /**
   * 计算用户在指定周期内的apr
   */
  const estimateApr = useMemo(() => {
    const { total_fee, total_user_value } = estimatedFee(user_bins)
    const periodDays = getPeriodDays(period)
    const day_rate = d(365).div(periodDays).mul(100)
    const apr = d(total_fee).div(total_user_value).mul(day_rate)
    return apr.toString()
  }, [period, user_bins, allBinList, feeDataObj])

  return {
    estimateApr,
    loading
  }
}
