import usePoolInfo from '@/hooks/common/usePoolInfo'
import useDlmmLiquidityStore from '@/store/dlmm'
import useAddDlmmLiquidityStore from '@/store/dlmm/addDlmmLiquidity'
import useTvlInfoStore from '@/store/dlmm/dlmmTvl'
import { AddressCopyLink, CetusTooltip } from '@cetus/design'
import useExplorer from '@cetus/hooks/src/useExplorer'
import useQueryParams from '@cetus/hooks/src/useQueryParams'
import { Icon, SingleCoinImage } from '@cetus/ui-kit'
import { d, textEllipses } from '@cetus/utils'
import { Box, Grid, Heading, HStack, Progress, Skeleton, Text, VStack } from '@chakra-ui/react'
import { FEE_PRECISION, FeeUtils, MAX_FEE_RATE } from 'dd_dlmm_sdk'
import InfoItem from '../../common/InfoItem'
import TokenCard from '../../common/TokenCard'

const getRatio = (value: string) => {
  if (value === '--') return '--'
  return `${value}%`
}

function PoolInfo() {
  const { dlmmApiPoolInfo, dlmmContractPoolInfo } = useDlmmLiquidityStore()
  const { fromToken, toToken } = useAddDlmmLiquidityStore()
  const { getExplorerUrl } = useExplorer()
  const { poolId } = useQueryParams()
  const { tokenAAmount, tokenBAmount, tokenAAmountUSD, tokenBAmountUSD, totalAmountUSD, tvlLoading } = useTvlInfoStore()
  const { tokenARatio, tokenBRatio } = usePoolInfo(tokenAAmountUSD, totalAmountUSD)

  const maxFee = `${d(MAX_FEE_RATE).div(FEE_PRECISION).mul(100)}%`
  const dynamicFee = dlmmContractPoolInfo?.variable_parameters ? FeeUtils?.getVariableFee(dlmmContractPoolInfo?.variable_parameters) : '--'
  return (
    <VStack
      w={{ base: '100%', lg: '482px' }}
      gap={{ base: '20px', lg: '40px' }}
      p={{ base: '20px 8px 8px', lg: '20px 16px' }}
      borderRadius="16px"
      border="1px solid"
      borderColor="border"
      bg="bg_secondary"
      minW={{ base: '100%', lg: '482px' }}
      maxW={{ base: '100%', lg: '482px' }}
    >
      <VStack gap="20px" w="100%">
        <HStack w="100%" justify="space-between">
          <Heading fontSize="16px" fontWeight="400">
            Pool Info
          </Heading>
        </HStack>
        <Grid templateColumns={{ base: 'repeat(1, 1fr)', lg: 'repeat(2, 1fr)' }} w="100%" gap={{ base: '12px', lg: '12px' }}>
          <InfoItem
            label="Address"
            value={
              <AddressCopyLink
                address={poolId || ''}
                fontSize="14px"
                color="text_caption"
                onClickLink={() => window.open(getExplorerUrl(poolId, 'poolAddress'))}
              />
            }
            wrapStyle={{ gridColumn: 'span 2' }}
          />
          <InfoItem label="Bin Step" value={dlmmContractPoolInfo?.binStep || '--'} />
          <InfoItem label="Pool ID" value={dlmmContractPoolInfo?.index ? `#${dlmmContractPoolInfo?.index}` : '--'} />
          <InfoItem label="Base Fee" value={dlmmApiPoolInfo?.feeDisplay ? dlmmApiPoolInfo?.feeDisplay : '--'} />
          <InfoItem
            label={
              <CetusTooltip tooltip="Max fee you may earn in each user swap">
                <HStack gap="2px" _hover={{ svg: { fill: 'text_caption' } }}>
                  <Text>Max Fee</Text>
                  <Icon xlinkHref="#icon-icon_tips" fontSize="18px" />
                </HStack>
              </CetusTooltip>
            }
            value={maxFee}
          />
          <InfoItem
            label={
              <CetusTooltip tooltip="Fee charged by protocol in each trade">
                <HStack gap="2px" _hover={{ svg: { fill: 'text_caption' } }}>
                  <Text>Protocol Fee</Text>
                  <Icon xlinkHref="#icon-icon_tips" fontSize="18px" />
                </HStack>
              </CetusTooltip>
            }
            value={dlmmApiPoolInfo?.protocolFeeRate ? `${dlmmApiPoolInfo.protocolFeeRate}%` : '--'}
          />
          <InfoItem label="Dynamic Fee" value={dynamicFee} />
        </Grid>
      </VStack>
      <VStack gap="20px" w="100%">
        <HStack justify="flex-start" w="100%">
          <Heading fontSize="16px" fontWeight="400">
            Pool Composition
          </Heading>
        </HStack>
        <VStack gap="16px" w="100%">
          <HStack w="100%" justify="space-between">
            <HStack gap="12px">
              <SingleCoinImage imageUrl={fromToken?.logo_url} w="28px" h="28px" coinType={fromToken ? fromToken?.coin_type : ''} />
              <VStack align="flex-start" gap="4px">
                <Text fontSize="16px" fontWeight="500" color="text_caption">
                  {textEllipses(fromToken?.symbol, 10)}
                </Text>
                {tvlLoading ? (
                  <Skeleton h="12px" w="46px" />
                ) : (
                  <Text fontSize="12px" fontWeight="500">
                    {false ? getRatio(tokenBRatio) : getRatio(tokenARatio)}
                  </Text>
                )}
              </VStack>
            </HStack>
            <Box w="200px">
              <Progress
                value={Number(false ? tokenBRatio : tokenARatio)}
                size="xs"
                h="4px"
                borderRadius="4px"
                bg={[tokenARatio, tokenBRatio].includes('--') ? 'border' : 'quote_green'}
                sx={{
                  'div[role="progressbar"]': {
                    bg: [tokenARatio, tokenBRatio].includes('--') ? 'background' : 'primary'
                  }
                }}
              />
            </Box>
            <HStack gap="12px">
              <VStack align="flex-end" gap="4px">
                <Text fontSize="16px" fontWeight="500" color="text_caption">
                  {textEllipses(toToken?.symbol, 10)}
                </Text>
                {tvlLoading ? (
                  <Skeleton h="12px" w="46px" />
                ) : (
                  <Text fontSize="12px" fontWeight="500">
                    {false ? getRatio(tokenARatio) : getRatio(tokenBRatio)}
                  </Text>
                )}
              </VStack>
              <SingleCoinImage imageUrl={toToken?.logo_url} w="28px" h="28px" coinType={toToken ? toToken?.coin_type : ''} />
            </HStack>
          </HStack>
          <VStack w="100%" flexDir={false ? 'column-reverse' : 'column'} gap="16px">
            <TokenCard loading={tvlLoading} token={fromToken} amount={tokenAAmount} amountUSD={tokenAAmountUSD} />
            <TokenCard loading={tvlLoading} token={toToken} amount={tokenBAmount} amountUSD={tokenBAmountUSD} />
          </VStack>
        </VStack>
      </VStack>
    </VStack>
  )
}

export default PoolInfo
